// Source list for the single-core openC910 + smart_run SoC testbench.
// Requires CODE_BASE_PATH (C910_RTL_FACTORY), SMART_PATH (smart_run), HERE (this
// directory's parent), C910_FILELIST and SYSMAP_INCDIR (generated by the Makefile)
// in the environment.

+libext+.v+.h+.V+.sv+

// Searched before the vendored mmu/rtl, so the generated sysmap.h shadows the
// one shipped with the RTL factory (main memory becomes cacheable).
+incdir+${SYSMAP_INCDIR}

+incdir+${CODE_BASE_PATH}/gen_rtl/cpu/rtl
+incdir+${CODE_BASE_PATH}/gen_rtl/mmu/rtl

// openC910 core, caches, MMU, BIU/CIU, PLIC/CLINT (the vendored list with one
// file substituted, see the Makefile)
-f ${C910_FILELIST}

// tc_sram behavioural model backing the C910 SRAM macros
${HERE}/rtl/tc_sram.sv

// smart_run SoC: AXI interconnect, 32 MB memory, UART/GPIO/timer, JTAG PMU
-y ${SMART_PATH}/logical/ahb
-y ${SMART_PATH}/logical/apb
-y ${SMART_PATH}/logical/axi
-y ${SMART_PATH}/logical/common
-y ${SMART_PATH}/logical/gpio
-y ${SMART_PATH}/logical/mem
-y ${SMART_PATH}/logical/uart
-y ${SMART_PATH}/logical/pmu

// Modules whose file name no longer matches the (patched) module name and so
// cannot be found through the -y library search path.
${SMART_PATH}/logical/pmu/sync.v
${SMART_PATH}/logical/gpio/gpio.v
